from typing import List

def repeatedRows(matrix: List[List[int]]) -> List[int]:
    seen = {}
    result = []
    for i, row in enumerate(matrix):
        key = tuple(row)
        if key in seen:
            result.append(i)
        else:
            seen[key] = i
    return result
